     '--version',
     '--repository',
     '--linux-x64-artifact',
     '--linux-arm64-artifact',
     '--macos-arm64-artifact',
     '--macos-team-id',
     '--output',
     '--acceptance-asset-directory',
     '--acceptance-unsigned-macos',
