import { createRequire } from 'node:module'
import { existsSync, readFileSync } from 'node:fs'
import { join, resolve } from 'node:path'
import { execFileSync } from 'node:child_process'

const repo = process.argv[2]
const require = createRequire(join(repo, 'package.json'))
const MarkdownIt = require('markdown-it')

const readme = readFileSync(join(repo, 'README.md'), 'utf8')
const pkg = JSON.parse(readFileSync(join(repo, 'package.json'), 'utf8'))
const scripts = pkg.scripts
const tracked = new Set(
  execFileSync('git', ['ls-files'], { cwd: repo, encoding: 'utf8' }).split('\n').filter(Boolean),
)
const trackedDirs = new Set()
for (const file of tracked) {
  const parts = file.split('/')
  for (let i = 1; i < parts.length; i++) trackedDirs.add(parts.slice(0, i).join('/'))
}

const md = new MarkdownIt({ html: ****** })
const tokens = md.parse(readme, {})
const errors = []

function slug(text) {
  return text
    .trim()
    .toLowerCase()
    .replace(/[^\p{L}\p{N}\s_-]/gu, '')
    .replace(/\s/g, '-')
}

const anchors = new Set()
const seen = new Map()
for (let i = 0; i < tokens.length; i++) {
  if (tokens[i].type === 'heading_open') {
    const inline = tokens[i + 1]
    const text = inline.children
      .filter((c) => c.type === 'text' || c.type === 'code_inline')
      .map((c) => c.content)
      .join('')
    let s = slug(text)
    const n = seen.get(s) ?? 0
    seen.set(s, n + 1)
    if (n > 0) s = `${s}-${n}`
    anchors.add(s)
  }
}

const hrefs = []
function walk(list) {
  for (const t of list) {
    if (t.type === 'link_open') hrefs.push(t.attrGet('href'))
    if (t.type === 'html_block' || t.type === 'html_inline') {
      for (const m of t.content.matchAll(/\b(?:src|href)="([^"]+)"/g)) hrefs.push(m[1])
    }
    if (t.children) walk(t.children)
  }
}
walk(tokens)

for (const href of hrefs) {
  if (/^https?:\/\//.test(href)) continue
  if (href.startsWith('#')) {
    if (!anchors.has(href.slice(1))) errors.push(`Missing anchor: ${href}`)
    continue
  }
  const [path] = href.split('#')
  const normalized = path.replace(/\/$/, '')
  const absolute = resolve(repo, normalized)
  if (!existsSync(absolute)) errors.push(`Missing path: ${href}`)
  else if (!tracked.has(normalized) && !trackedDirs.has(normalized))
    errors.push(`Path exists but is not tracked by git: ${href}`)
}

const npmRuns = [...readme.matchAll(/npm run ([a-z][\w:.-]*)/g)].map((m) => m[1])
for (const name of npmRuns) if (!scripts[name]) errors.push(`Unknown npm script: ${name}`)
if (/\bnpm test\b/.test(readme) && !scripts.test) errors.push('npm test has no script')

const bareScriptNames = ['check-seams', 'check-adrs', 'architecture:check', 'architecture:report', 'lint', 'typecheck', 'test', 'verify', 'dev', 'build', 'pack:mac:arm64:signed', 'test:watch']
for (const name of bareScriptNames) {
  if (readme.includes(`\`${name}\``) && !scripts[name]) errors.push(`Unknown bare script: ${name}`)
}

const envNames = [...new Set([...readme.matchAll(/\b(HVIR_[A-Z_]+)\b/g)].map((m) => m[1]))]
for (const name of envNames) {
  let found = false
  try {
    execFileSync('git', ['grep', '-q', '-F', name, '--', 'src', 'scripts', '.github'], { cwd: repo })
    found = ******
  } catch {}
  if (!found) errors.push(`Env var not referenced in code: ${name}`)
}

const scenarioSource = readFileSync(join(repo, 'src/main/smoke/scenario-selection.mts'), 'utf8')
for (const m of readme.matchAll(/npm run smoke:scenario -- ([\w -]+?)\s*(?:#|$)/gm)) {
  for (const name of m[1].trim().split(/\s+/)) {
    if (!scenarioSource.includes(`'${name}'`)) errors.push(`Unknown smoke scenario: ${name}`)
  }
}

console.log(`links checked: ${hrefs.length}; anchors: ${[...anchors].length}; npm run refs: ${npmRuns.length}; env vars: ${envNames.join(', ')}`)
if (errors.length) {
  console.error(errors.join('\n'))
  process.exit(1)
}
